/* The chrome around a document: a header, a rail of page previews, the page.
 *
 * One header for every kind of file the panel opens, so that a Word document,
 * a deck and a PDF are the same thing to read even though three different
 * renderers draw them. Modelled on Extend UI's document viewer toolbar:
 * a rail toggle and the page count on the left, then rotation, zoom, search
 * and an overflow on the right, in groups separated by hairlines.
 *
 * **Every control is optional and absent by default.** A renderer that cannot
 * rotate is not given a rotate handler, and the button is then not rendered
 * rather than rendered dead — a spreadsheet has no pages to count and a Word
 * document cannot rotate, and a toolbar that offered either would be lying.
 * That is why this takes a dozen small props instead of a `features` flag.
 *
 * The rail's breakpoint measures the *container*, not the window: the panel
 * is a drawer whose width is a fraction of the page, so a media query would
 * be asking about the wrong box. Above the breakpoint the rail sits beside
 * the page; below, it comes over it.
 *
 * Nothing here names a colour — see `assets/css/mail-archive.css`, keyed on
 * the `ma-viewer-*` classes.
 */

import { Component, useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import {
  ChevronDown,
  Minus,
  PanelLeft,
  Plus,
  RotateCcw,
  RotateCw,
  Search,
  X,
} from "lucide-react";

const INLINE_MIN_WIDTH = 768;
/* Below this many pixels of container the rail stops being a column beside
 * the page and becomes something you pull over it. Extend's own figure, kept
 * because it is the width at which a page plus a 160px rail stops leaving a
 * readable column. */

const ZOOM_STEPS = [50, 75, 100, 125, 150, 200, 400];

/* The one thing a function component cannot be. Each viewer here hands a
 * vendored WASM parser a file somebody else wrote, and a malformed .docx or
 * .pptx — routine in a real archive — makes several of those throw
 * *synchronously during render* rather than rejecting a promise. React's
 * answer to a throw in render is to unmount the whole tree above it, so
 * without this the panel vanished and `preview.py`'s promise that every file
 * gets a panel was broken by exactly the files that most need one.
 *
 * Deliberately not a retry: the bytes will not parse the second time either.
 * It says which file failed and leaves the rest of the page alone. */
export class ViewerBoundary extends Component {
  constructor(props) {
    super(props);
    this.state = { failed: false };
  }

  static getDerivedStateFromError() {
    return { failed: true };
  }

  componentDidCatch(error) {
    console.error("The viewer could not read this file", error);
  }

  render() {
    if (!this.state.failed) return this.props.children;
    return (
      <div className="ma-viewer-broken" role="status">
        <p>This file could not be displayed.</p>
        <p className="ma-viewer-broken-detail">
          {this.props.fileName
            ? `${this.props.fileName} is damaged, or uses a feature this viewer does not read.`
            : "It is damaged, or uses a feature this viewer does not read."}{" "}
          You can still download it.
        </p>
      </div>
    );
  }
}

/* The wrapper every viewer in this folder is exported through.
 *
 * A helper rather than four hand-written wrappers, because the wrapping is the
 * kind of step that is only noticed when it is missing: `viewer_pdf.jsx` was
 * exported bare for exactly as long as this was three copies of the same four
 * lines. `test_ui_kit_components.py` asserts that every `viewer_*.jsx` calls
 * this, so a fifth viewer cannot repeat that.
 *
 * The displayed name is kept so React's own stack traces still say which
 * viewer failed rather than naming the wrapper four times. */
export function withBoundary(Inner) {
  const Wrapped = (props) => (
    <ViewerBoundary fileName={props.fileName}>
      <Inner {...props} />
    </ViewerBoundary>
  );
  Wrapped.displayName = `WithBoundary(${Inner.displayName || Inner.name})`;
  return Wrapped;
}

export function useContainerWidth() {
  const ref = useRef(null);
  const [width, setWidth] = useState(0);
  useLayoutEffect(() => {
    const element = ref.current;
    if (!element) return undefined;
    const measure = () => {
      const next = element.getBoundingClientRect().width;
      /* Keep the last real measurement while the element is hidden. A drawer
       * that has just closed measures zero, and re-laying the viewer out for
       * that would drop every rendered canvas and flash on the way back. */
      if (next === 0) return;
      setWidth(next);
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  return [ref, width];
}

function IconButton({ label, onClick, pressed, children }) {
  return (
    <button
      type="button"
      className="ma-viewer-icon"
      aria-label={label}
      aria-pressed={pressed === undefined ? undefined : String(pressed)}
      onClick={onClick}
    >
      {children}
    </button>
  );
}

function Divider() {
  return <span className="ma-viewer-divider" role="presentation" />;
}

/* One page button. Split out because it owns an IntersectionObserver: a
 * two-hundred-page PDF must not rasterise two hundred previews on mount, so a
 * thumbnail is painted when it is first scrolled near. */
function Thumb({ item, active, onPick, renderThumb }) {
  const ref = useRef(null);
  const [seen, setSeen] = useState(false);

  useEffect(() => {
    if (seen || !ref.current) return undefined;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((one) => one.isIntersecting)) setSeen(true);
      },
      { rootMargin: "200px" },
    );
    observer.observe(ref.current);
    return () => observer.disconnect();
  }, [seen]);

  return (
    <button
      ref={ref}
      type="button"
      className="ma-viewer-thumb"
      aria-current={active ? "true" : undefined}
      aria-label={`Page ${item.number}`}
      tabIndex={active ? 0 : -1}
      onClick={() => onPick(item.index)}
    >
      {/* The aspect comes from the document, not from this file. A slide is
        * 16:9 and a letter is A4, and a preview that assumed either would
        * letterbox the other into a strip at the top of a tall white box. */}
      <span
        className="ma-viewer-thumb-page"
        style={item.aspect ? { aspectRatio: item.aspect } : undefined}
      >
        {seen ? renderThumb(item) : null}
      </span>
      <span className="ma-viewer-thumb-number">{item.number}</span>
    </button>
  );
}

export function ViewerShell({
  rootRef = null,
  items = null,
  pageCount = null,
  rail = null,
  active = 0,
  onPick = () => {},
  renderThumb = () => null,
  label = "Page",
  zoom = null,
  onZoom = null,
  onRotate = null,
  onSearch = null,
  extras = null,
  children,
}) {
  const [ref, width] = useContainerWidth();
  const inline = width >= INLINE_MIN_WIDTH;
  const [open, setOpen] = useState(true);
  const [query, setQuery] = useState(null);
  const railRef = useRef(null);

  /* Two ways to have a rail, because the four renderers do not agree on what
   * a page preview is. Three of them hand over a list and let this draw it;
   * `@embedpdf` brings its own virtualised pane — the right thing for a
   * two-hundred-page document — and hands the whole rail over instead. The
   * header reads the same either way, which is the point of the shell. */
  const pages = pageCount ?? items?.length ?? 0;
  const hasRail = pages > 1;

  /* An overlay rail left open when the panel is narrowed would sit on top of
   * the page; one left closed when it is widened would waste the room. */
  useEffect(() => setOpen(inline), [inline]);

  const showRail = hasRail && open;

  /* Roving tabindex: the rail is one tab stop and the arrows move within it.
   * None of the renderers can supply this once the rail is ours. */
  const onKeyDown = useCallback(
    (event) => {
      const step = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 }[
        event.key
      ];
      if (!step) return;
      event.preventDefault();
      const next = Math.min(Math.max(active + step, 0), pages - 1);
      if (next !== active) onPick(next);
    },
    [active, pages, onPick],
  );

  useEffect(() => {
    railRef.current
      ?.querySelector('[aria-current="true"]')
      ?.scrollIntoView({ block: "nearest" });
  }, [active]);

  const step = (by) => {
    /* A viewer may hand us a zoom of its own — "fit width" is computed from
     * the page, not picked from this table — and that can sit above the last
     * step. `findIndex` answers -1 there, and -1 + by clamped at 0 sent both
     * buttons to the smallest step instead of stepping down from the top. */
    const found = ZOOM_STEPS.findIndex((one) => one >= zoom);
    const at = found === -1 ? ZOOM_STEPS.length : found;
    const next = ZOOM_STEPS[Math.min(Math.max(at + by, 0), ZOOM_STEPS.length - 1)];
    if (next !== zoom) onZoom(next);
  };

  /* Two refs on one node: this file measures the container, and a viewer may
   * need to reach into what it rendered — the Word document scrolls itself to
   * a page the rail picked. */
  const attach = useCallback(
    (node) => {
      ref.current = node;
      if (rootRef) rootRef.current = node;
    },
    [ref, rootRef],
  );

  return (
    <div
      ref={attach}
      className="ma-viewer-shell"
      data-rail={showRail ? "open" : "closed"}
      data-rail-mode={inline ? "inline" : "overlay"}
    >
      <header className="ma-viewer-header">
        {hasRail ? (
          <IconButton
            label={showRail ? `Hide ${label}s` : `Show ${label}s`}
            pressed={showRail}
            onClick={() => setOpen((was) => !was)}
          >
            <PanelLeft size={18} strokeWidth={1.75} />
          </IconButton>
        ) : null}
        {pages ? (
          <p className="ma-viewer-count">
            {label} <b>{active + 1}</b> of {pages}
          </p>
        ) : null}

        <span className="ma-viewer-spacer" />

        {onRotate ? (
          <>
            <IconButton label="Rotate left" onClick={() => onRotate(-90)}>
              <RotateCcw size={18} strokeWidth={1.75} />
            </IconButton>
            <IconButton label="Rotate right" onClick={() => onRotate(90)}>
              <RotateCw size={18} strokeWidth={1.75} />
            </IconButton>
            <Divider />
          </>
        ) : null}

        {onZoom ? (
          <>
            <IconButton label="Zoom out" onClick={() => step(-1)}>
              <Minus size={18} strokeWidth={1.75} />
            </IconButton>
            <span className="ma-viewer-zoom">
              <select
                aria-label="Zoom"
                value={ZOOM_STEPS.includes(zoom) ? zoom : ""}
                onChange={(event) => onZoom(Number(event.target.value))}
              >
                {ZOOM_STEPS.includes(zoom) ? null : (
                  <option value="">{Math.round(zoom)}%</option>
                )}
                {ZOOM_STEPS.map((one) => (
                  <option key={one} value={one}>
                    {one}%
                  </option>
                ))}
              </select>
              <ChevronDown size={14} strokeWidth={2} aria-hidden="true" />
            </span>
            <IconButton label="Zoom in" onClick={() => step(1)}>
              <Plus size={18} strokeWidth={1.75} />
            </IconButton>
          </>
        ) : null}

        {onSearch ? (
          <>
            <Divider />
            {query === null ? (
              <IconButton label="Search this file" onClick={() => setQuery("")}>
                <Search size={18} strokeWidth={1.75} />
              </IconButton>
            ) : (
              <span className="ma-viewer-find">
                <Search size={15} strokeWidth={1.75} aria-hidden="true" />
                <input
                  autoFocus
                  type="search"
                  aria-label="Search this file"
                  placeholder="Find"
                  value={query}
                  onChange={(event) => {
                    setQuery(event.target.value);
                    onSearch(event.target.value);
                  }}
                  onKeyDown={(event) => {
                    if (event.key === "Escape") {
                      setQuery(null);
                      onSearch("");
                    }
                  }}
                />
                <button
                  type="button"
                  aria-label="Close search"
                  onClick={() => {
                    setQuery(null);
                    onSearch("");
                  }}
                >
                  <X size={14} strokeWidth={2} />
                </button>
              </span>
            )}
          </>
        ) : null}

        {extras}
      </header>

      <div className="ma-viewer-body">
        {hasRail ? (
          <nav
            ref={railRef}
            className="ma-viewer-rail"
            /* A caller-supplied rail brings its own virtualiser: it positions
             * rows absolutely and scrolls itself, so the padding and the
             * overflow this file would otherwise apply have to come off. */
            data-rail-kind={rail ? "pane" : "list"}
            aria-label={`${label}s`}
            onKeyDown={onKeyDown}
            hidden={!showRail}
          >
            {rail ??
              items?.map((one) => (
                <Thumb
                  key={one.index}
                  item={one}
                  active={one.index === active}
                  onPick={onPick}
                  renderThumb={renderThumb}
                />
              ))}
          </nav>
        ) : null}
        {!inline && showRail ? (
          <div
            className="ma-viewer-scrim"
            role="presentation"
            onClick={() => setOpen(false)}
          />
        ) : null}
        <div className="ma-viewer-page">{children}</div>
      </div>
    </div>
  );
}
/* A PDF, rendered in the browser from bytes.
 *
 * This one replaced something that already worked: the panel used to point an
 * `<iframe>` at a `data:` URI and let the browser's own plugin draw it. That
 * was fine and it is gone for one reason — it was the only one of the four
 * document kinds with no page rail and no shared header, so a reader who
 * opened a deck and then an invoice got two different things.
 *
 * `@embedpdf/*` is what Extend UI's own PDF viewer is built on. It is
 * headless: every capability is a plugin, and the ones registered below are
 * exactly the ones the header offers. Nothing is registered speculatively.
 *
 * **Two overrides here are load-bearing and must not be dropped.**
 * `usePdfiumEngine` defaults to fetching its WebAssembly from
 * `cdn.jsdelivr.net`, and its font fallback pulls typefaces from the same
 * place. Either would be invisible on a developer machine with internet and
 * fatal in the offline desktop bundle — and both would break the archive's
 * posture that the browser never fetches anything. So the wasm arrives as a
 * bundled asset through Vite's `?url`, and the font fallback is turned off
 * outright, which the library documents as "no external font requests".
 * `test_ui_kit_components.py` fails on any absolute URL in this folder.
 */

import { useCallback, useMemo } from "react";
import { createPluginRegistration } from "@embedpdf/core";
import { EmbedPDF } from "@embedpdf/core/react";
import { usePdfiumEngine } from "@embedpdf/engines/react";
import pdfiumWasmUrl from "@embedpdf/pdfium/pdfium.wasm?url";
import {
  DocumentContent,
  DocumentManagerPluginPackage,
  useActiveDocument,
  useOpenDocuments,
} from "@embedpdf/plugin-document-manager/react";
import { InteractionManagerPluginPackage } from "@embedpdf/plugin-interaction-manager/react";
import { RenderLayer, RenderPluginPackage } from "@embedpdf/plugin-render/react";
import { RotatePluginPackage, useRotate } from "@embedpdf/plugin-rotate/react";
import { ScrollPluginPackage, Scroller, useScroll } from "@embedpdf/plugin-scroll/react";
import {
  ThumbImg,
  ThumbnailPluginPackage,
  ThumbnailsPane,
} from "@embedpdf/plugin-thumbnail/react";
import { Viewport, ViewportPluginPackage } from "@embedpdf/plugin-viewport/react";
import { ZoomPluginPackage, useZoom } from "@embedpdf/plugin-zoom/react";

import { useBuffer } from "./viewer_bytes.js";
import { ViewerShell, withBoundary } from "./viewer_shell.jsx";

function PdfDocument({ encoded = "", fileName = "" }) {
  const buffer = useBuffer(encoded);
  const { engine, error: engineError } = usePdfiumEngine({
    wasmUrl: pdfiumWasmUrl,
    fontFallback: null,
    /* Main thread rather than a worker. The worker build resolves its own
     * wasm with `import.meta.url` from inside the worker chunk, which under
     * Vite points at the dependency cache where the file is not — the same
     * failure `maps_base/maps.jsx` documents for maplibre, except that
     * `usePdfiumEngine` swallows it and the document simply never leaves
     * "loading". Measured: with the worker, status stayed `loading` forever
     * and no error was raised. An attachment is capped by `PREVIEW_LIMIT` in
     * `message_detail/preview.py`; the number is not restated here, because it
     * was raised once already and this comment went on claiming the old one. */
    worker: false,
  });

  /* Memoised on the bytes, and that is not an optimisation. `EmbedPDF` reads
   * this list to build its plugin registry; a fresh array on every render
   * tears the registry down and rebuilds it, so the document never finishes
   * opening and the viewport keeps registering against a document that is not
   * there yet. Same trap `graph_canvas.jsx` documents about Reflex handing
   * down fresh arrays with every state delta. */
  const plugins = useMemo(
    () =>
      buffer
        ? [
            /* The document is handed over as bytes. This is why the viewer
             * needs no URL, and therefore no route that serves archived mail
             * — see `message_detail/preview.py` for that argument. */
            createPluginRegistration(DocumentManagerPluginPackage, {
              initialDocuments: [
                {
                  buffer,
                  name: fileName || "document.pdf",
                  autoActivate: true,
                },
              ],
            }),
            createPluginRegistration(ViewportPluginPackage),
            createPluginRegistration(ScrollPluginPackage),
            createPluginRegistration(RenderPluginPackage),
            createPluginRegistration(InteractionManagerPluginPackage),
            createPluginRegistration(ZoomPluginPackage),
            createPluginRegistration(RotatePluginPackage),
            /* The pane reserves each row as `imagePadding * 2 + height +
             * labelHeight`, and its defaults are 0 and 16 — a preview with
             * its highlight drawn tight against its edges. These are the
             * measurements the rail is actually drawn at, so the pane has to
             * be told them rather than have CSS add padding it did not
             * reserve, which would put the highlight off the row. */
            createPluginRegistration(ThumbnailPluginPackage, {
              width: 116,
              imagePadding: 14,
              labelHeight: 24,
              gap: 10,
              paddingY: 12,
            }),
          ]
        : null,
    [buffer, fileName],
  );

  if (engineError) {
    return <p className="ma-viewer-state">This PDF could not be opened.</p>;
  }
  if (!plugins || !engine) return null;

  return (
    <EmbedPDF
      engine={engine}
      plugins={plugins}
      autoMountDomElements={false}
    >
      <Opened fileName={fileName} />
    </EmbedPDF>
  );
}

/* Wrapped rather than exported bare, like every viewer beside it.
 *
 * The `isError` branch in `Opened` below catches a PDF that pdfium *reports*
 * it cannot parse. It does not catch pdfium throwing out of a render, which is
 * a different failure with the same cause, and this viewer went without the
 * boundary for as long as each viewer wrote its own wrapper by hand. See
 * `ViewerBoundary` in `viewer_shell.jsx`. */
export default withBoundary(PdfDocument);

/* Every component and hook below takes an explicit `documentId`, and the
 * viewport refuses to register against a document that is not open yet —
 * "document must be opened before registering viewport", which is what it
 * says if you mount it eagerly. `DocumentContent` is the library's own gate
 * for that, so nothing inside it renders until the bytes are parsed. */
function Opened({ fileName }) {
  const { activeDocumentId } = useActiveDocument();
  const open = useOpenDocuments();

  /* Falling back to the first open document is not defensiveness. A viewer
   * built from `initialDocuments` has exactly one, and `autoActivate` does
   * not reliably mark it active before the first render — measured: the
   * manager reports one open document while `activeDocumentId` is still
   * null, and everything downstream needs an id. With one document, "the
   * active one" and "the only one" cannot disagree. */
  const documentId = activeDocumentId ?? open[0]?.id ?? null;

  if (!documentId) return null;

  return (
    <DocumentContent documentId={documentId}>
      {({ documentState, isLoaded, isError }) => {
        if (isLoaded) return <Pages documentId={documentId} fileName={fileName} />;
        /* A PDF that will not open is the one case the old `<iframe>` handled
         * by showing the browser's own error. Saying it here keeps the panel's
         * rule that every file gets a sentence rather than a blank rectangle —
         * an encrypted or truncated invoice is common enough in mail. */
        return (
          <p className="ma-viewer-state" data-status={documentState?.status}>
            {isError
              ? (documentState?.error ?? "This PDF could not be opened.")
              : "Opening…"}
          </p>
        );
      }}
    </DocumentContent>
  );
}

function Pages({ documentId: activeDocumentId, fileName }) {
  const { state: scroll, provides: scroller } = useScroll(activeDocumentId);
  const { state: zoom, provides: zoomer } = useZoom(activeDocumentId);
  const { provides: rotator } = useRotate(activeDocumentId);

  const pick = useCallback(
    (index) => scroller?.scrollToPage({ pageNumber: index + 1 }),
    [scroller],
  );
  const onZoom = useCallback(
    (percent) => zoomer?.requestZoom(percent / 100),
    [zoomer],
  );
  const onRotate = useCallback(
    (degrees) => (degrees > 0 ? rotator?.rotateForward() : rotator?.rotateBackward()),
    [rotator],
  );

  const pages = scroll?.totalPages ?? 0;
  const page = (scroll?.currentPage ?? 1) - 1;

  /* embedpdf brings its own virtualised thumbnail pane, so the shell is given
   * the rail whole rather than a list of items to draw. A two-hundred-page
   * PDF is exactly the case that pane exists for. */
  /* `ThumbMeta` carries the geometry and the pane is virtualised: each row is
   * positioned absolutely at its own `top` inside a container the pane sizes.
   * Every field below is one the pane computed — inventing a `wrapperStyle`
   * and leaving `top` off puts all five pages at zero and shows one. */
  const rail =
    pages > 1 ? (
      <ThumbnailsPane documentId={activeDocumentId} style={{ height: "100%" }}>
        {(meta) => (
          <div
            key={meta.pageIndex}
            style={{
              position: "absolute",
              top: meta.top,
              height: meta.wrapperHeight,
              width: "100%",
            }}
          >
            <button
              type="button"
              className="ma-viewer-thumb"
              aria-current={meta.pageIndex === page ? "true" : undefined}
              aria-label={`Page ${meta.pageIndex + 1}`}
              onClick={() => pick(meta.pageIndex)}
              /* The pane reserved `padding * 2 + height + labelHeight` for
               * this row, so the button spends it the same way. Any other
               * padding here and the highlight would be a box that does not
               * line up with the row the pane positioned. */
              style={{ padding: meta.padding ?? 8 }}
            >
              <span
                className="ma-viewer-thumb-page"
                style={{ width: meta.width, height: meta.height }}
              >
                <ThumbImg meta={meta} documentId={activeDocumentId} />
              </span>
              <span
                className="ma-viewer-thumb-number"
                style={{ height: meta.labelHeight, padding: 0, lineHeight: `${meta.labelHeight}px` }}
              >
                {meta.pageIndex + 1}
              </span>
            </button>
          </div>
        )}
      </ThumbnailsPane>
    ) : null;

  return (
    <ViewerShell
      label="Page"
      pageCount={pages}
      active={page}
      onPick={pick}
      rail={rail}
      zoom={Math.round((zoom?.currentZoomLevel ?? 1) * 100)}
      onZoom={onZoom}
      onRotate={onRotate}
    >
      <Viewport
        documentId={activeDocumentId}
        style={{ height: "100%" }}
        aria-label={fileName}
      >
        <Scroller
          documentId={activeDocumentId}
          renderPage={({ width, height, pageIndex, scale }) => (
            /* The sheet is drawn by us, not by the renderer: `RenderLayer`
             * paints an `<img>` of the page content and nothing else, so
             * without this a page has no edge, an unrendered one is invisible,
             * and a scrolled document reads as text floating in a void. */
            <div className="ma-viewer-sheet" style={{ width, height }}>
              <RenderLayer
                documentId={activeDocumentId}
                pageIndex={pageIndex}
                scale={scale}
                style={{ width: "100%", height: "100%", display: "block" }}
              />
            </div>
          )}
        />
      </Viewport>
    </ViewerShell>
  );
}
/* A Word document, rendered in the browser from bytes.
 *
 * The conventions are the ones `viewer_pptx.jsx` documents. Three things are
 * specific to this one:
 *
 * 1. It is the only viewer here that has to *import* rather than be handed a
 *    source. `useDocxEditor` returns a controller and the document arrives
 *    through `controller.importDocxFile(File)`, so the decoded bytes are
 *    wrapped in a `File` and pushed in from an effect.
 *
 * 2. `mode="read-only"`. The library's viewer is an editor with editing
 *    turned off; this is an archive, and a Word document a reader could
 *    silently alter is a correctness problem, not a cosmetic one.
 *
 * 3. Page previews are painted, not fetched. `useDocxPageThumbnails` gives a
 *    `paintThumbnail(pageIndex, canvas)` rather than an image URL, so each
 *    rail entry is a `<canvas>` whose ref callback asks for the paint.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import {
  DocxEditorViewer,
  setWasmSource,
  useDocxEditor,
  useDocxPageThumbnails,
} from "@extend-ai/react-docx";
import docxWasmUrl from "@extend-ai/react-docx/docx_wasm_bg.wasm?url";

import { useDecoded } from "./viewer_bytes.js";
