input.content:
/* The frame around a document: header, page rail and page.
 *
 * Ported from the mail-archive viewer kit. PDF, Word and PowerPoint get the
 * same header although three different renderers draw them. Every control is
 * optional: a renderer that cannot rotate gets no rotate button.
 *
 * The rail breakpoint measures the container, not the window, because the
 * viewer sits in a dialog. Colours live in `assets/css/aq-viewer.css`.
 */

import { Component, useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import {
  ChevronDown,
  Minus,
  PanelLeft,
  Plus,
  RotateCcw,
  RotateCw,
  Search,
  X,
} from "lucide-react";

const INLINE_MIN_WIDTH = 768;

const ZOOM_STEPS = [50, 75, 100, 125, 150, 200, 400];

/* The WASM parsers throw during render on a damaged file. Without a boundary
 * React unmounts the whole dialog; with it the file says it cannot be shown. */
export class ViewerBoundary extends Component {
  constructor(props) {
    super(props);
    this.state = { failed: false };
  }

  static getDerivedStateFromError() {
    return { failed: true };
  }

  componentDidCatch(error) {
    console.error("The viewer could not read this file", error);
  }

  render() {
    if (!this.state.failed) return this.props.children;
    return (
      <div className="aq-viewer-broken" role="status">
        <p>Diese Datei kann nicht angezeigt werden.</p>
        <p className="aq-viewer-broken-detail">
          {this.props.fileName
            ? `${this.props.fileName} ist beschädigt oder nutzt Funktionen, die die Vorschau nicht liest.`
            : "Die Datei ist beschädigt oder nutzt Funktionen, die die Vorschau nicht liest."}{" "}
          Der gelesene Text bleibt verfügbar.
        </p>
      </div>
    );
  }
}

/* Every viewer is exported through this, so none can ship without the boundary. */
export function withBoundary(Inner) {
  const Wrapped = (props) => (
    <ViewerBoundary fileName={props.fileName}>
      <Inner {...props} />
    </ViewerBoundary>
  );
  Wrapped.displayName = `WithBoundary(${Inner.displayName || Inner.name})`;
  return Wrapped;
}

export function useContainerWidth() {
  const ref = useRef(null);
  const [width, setWidth] = useState(0);
  useLayoutEffect(() => {
    const element = ref.current;
    if (!element) return undefined;
    const measure = () => {
      const next = element.getBoundingClientRect().width;
      /* A closing dialog measures zero; keep the last real width. */
      if (next === 0) return;
      setWidth(next);
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  return [ref, width];
}

function IconButton({ label, onClick, pressed, children }) {
  return (
    <button
      type="button"
      className="aq-viewer-icon"
      aria-label={label}
      title={label}
      aria-pressed={pressed === undefined ? undefined : String(pressed)}
      onClick={onClick}
    >
      {children}
    </button>
  );
}

function Divider() {
  return <span className="aq-viewer-divider" role="presentation" />;
}

/* Paints its preview only when first scrolled near, so a long document does
 * not rasterise every page on mount. */
function Thumb({ item, active, onPick, renderThumb, label }) {
  const ref = useRef(null);
  const [seen, setSeen] = useState(false);

  useEffect(() => {
    if (seen || !ref.current) return undefined;
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((one) => one.isIntersecting)) setSeen(true);
      },
      { rootMargin: "200px" },
    );
    observer.observe(ref.current);
    return () => observer.disconnect();
  }, [seen]);

  return (
    <button
      ref={ref}
      type="button"
      className="aq-viewer-thumb"
      aria-current={active ? "true" : undefined}
      aria-label={`${label} ${item.number}`}
      tabIndex={active ? 0 : -1}
      onClick={() => onPick(item.index)}
    >
      <span
        className="aq-viewer-thumb-page"
        style={item.aspect ? { aspectRatio: item.aspect } : undefined}
      >
        {seen ? renderThumb(item) : null}
      </span>
      <span className="aq-viewer-thumb-number">{item.number}</span>
    </button>
  );
}

export function ViewerShell({
  rootRef = null,
  items = null,
  pageCount = null,
  rail = null,
  active = 0,
  onPick = () => {},
  renderThumb = () => null,
  label = "Seite",
  railLabel = "Seiten",
  zoom = null,
  onZoom = null,
  onRotate = null,
  onSearch = null,
  extras = null,
  children,
}) {
  const [ref, width] = useContainerWidth();
  const inline = width >= INLINE_MIN_WIDTH;
  const [open, setOpen] = useState(true);
  const [query, setQuery] = useState(null);
  const railRef = useRef(null);

  /* Word and PowerPoint hand over a list of items; embedpdf brings its own
   * virtualised pane and hands over the whole rail. */
  const pages = pageCount ?? items?.length ?? 0;
  const hasRail = pages > 1;

  useEffect(() => setOpen(inline), [inline]);

  const showRail = hasRail && open;

  /* Roving tabindex: the rail is one tab stop and the arrows move within it. */
  const onKeyDown = useCallback(
    (event) => {
      const step = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 }[
        event.key
      ];
      if (!step) return;
      event.preventDefault();
      const next = Math.min(Math.max(active + step, 0), pages - 1);
      if (next !== active) onPick(next);
    },
    [active, pages, onPick],
  );

  useEffect(() => {
    railRef.current
      ?.querySelector('[aria-current="true"]')
      ?.scrollIntoView({ block: "nearest" });
  }, [active]);

  const step = (by) => {
    /* "Fit width" can sit above the last step; findIndex is -1 there. */
    const found = ZOOM_STEPS.findIndex((one) => one >= zoom);
    const at = found === -1 ? ZOOM_STEPS.length : found;
    const next = ZOOM_STEPS[Math.min(Math.max(at + by, 0), ZOOM_STEPS.length - 1)];
    if (next !== zoom) onZoom(next);
  };

  /* Two refs on one node: the shell measures it, the Word viewer scrolls in it. */
  const attach = useCallback(
    (node) => {
      ref.current = node;
      if (rootRef) rootRef.current = node;
    },
    [ref, rootRef],
  );

  return (
    <div
      ref={attach}
      className="aq-viewer-shell"
      data-rail={showRail ? "open" : "closed"}
      data-rail-mode={inline ? "inline" : "overlay"}
    >
      <header className="aq-viewer-header">
        {hasRail ? (
          <IconButton
            label={showRail ? `${railLabel} ausblenden` : `${railLabel} einblenden`}
            pressed={showRail}
            onClick={() => setOpen((was) => !was)}
          >
            <PanelLeft size={18} strokeWidth={1.75} />
          </IconButton>
        ) : null}
        {pages ? (
          <p className="aq-viewer-count">
            {label} <b>{active + 1}</b> von {pages}
          </p>
        ) : null}

        <span className="aq-viewer-spacer" />

        {onRotate ? (
          <>
            <IconButton label="Nach links drehen" onClick={() => onRotate(-90)}>
              <RotateCcw size={18} strokeWidth={1.75} />
            </IconButton>
            <IconButton label="Nach rechts drehen" onClick={() => onRotate(90)}>
              <RotateCw size={18} strokeWidth={1.75} />
            </IconButton>
            <Divider />
          </>
        ) : null}

        {onZoom ? (
          <>
            <IconButton label="Verkleinern" onClick={() => step(-1)}>
              <Minus size={18} strokeWidth={1.75} />
            </IconButton>
            <span className="aq-viewer-zoom">
              <select
                aria-label="Zoom"
                value={ZOOM_STEPS.includes(zoom) ? zoom : ""}
                onChange={(event) => onZoom(Number(event.target.value))}
              >
                {ZOOM_STEPS.includes(zoom) ? null : (
                  <option value="">{Math.round(zoom)} %</option>
                )}
                {ZOOM_STEPS.map((one) => (
                  <option key={one} value={one}>
                    {one} %
                  </option>
                ))}
              </select>
              <ChevronDown size={14} strokeWidth={2} aria-hidden="true" />
            </span>
            <IconButton label="Vergrößern" onClick={() => step(1)}>
              <Plus size={18} strokeWidth={1.75} />
            </IconButton>
          </>
        ) : null}

        {onSearch ? (
          <>
            <Divider />
            {query === null ? (
              <IconButton label="In der Datei suchen" onClick={() => setQuery("")}>
                <Search size={18} strokeWidth={1.75} />
              </IconButton>
            ) : (
              <span className="aq-viewer-find">
                <Search size={15} strokeWidth={1.75} aria-hidden="true" />
                <input
                  autoFocus
                  type="search"
                  aria-label="In der Datei suchen"
                  placeholder="Suchen"
                  value={query}
                  onChange={(event) => {
                    setQuery(event.target.value);
                    onSearch(event.target.value);
                  }}
                  onKeyDown={(event) => {
                    if (event.key === "Escape") {
                      /* Escape closes the search, not the dialog. */
                      event.stopPropagation();
                      setQuery(null);
                      onSearch("");
                    }
                  }}
                />
                <button
                  type="button"
                  aria-label="Suche schließen"
                  onClick={() => {
                    setQuery(null);
                    onSearch("");
                  }}
                >
                  <X size={14} strokeWidth={2} />
                </button>
              </span>
            )}
          </>
        ) : null}

        {extras}
      </header>

      <div className="aq-viewer-body">
        {hasRail ? (
          <nav
            ref={railRef}
            className="aq-viewer-rail"
            /* A caller-supplied rail virtualises itself and owns its scrolling. */
            data-rail-kind={rail ? "pane" : "list"}
            aria-label={railLabel}
            onKeyDown={onKeyDown}
            hidden={!showRail}
          >
            {rail ??
              items?.map((one) => (
                <Thumb
                  key={one.index}
                  item={one}
                  active={one.index === active}
                  onPick={onPick}
                  renderThumb={renderThumb}
                  label={label}
                />
              ))}
          </nav>
        ) : null}
        {!inline && showRail ? (
          <div
            className="aq-viewer-scrim"
            role="presentation"
            onClick={() => setOpen(false)}
          />
        ) : null}
        <div className="aq-viewer-page">{children}</div>
      </div>
    </div>
  );
}

/* Base64 to bytes. The viewers get their file as a base64 prop over the
 * state socket, so no route serves source files. */

import { useMemo } from "react";

/* atob yields one character per byte. A TextEncoder would re-encode as UTF-8
 * and corrupt every byte above 0x7f. */
export function decodeBase64(encoded) {
  const binary = atob(encoded);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

/* Keyed on the payload: Reflex re-renders on every state delta and decoding
 * megabytes each time is the only expensive step here. */
export function useDecoded(encoded) {
  return useMemo(() => (encoded ? decodeBase64(encoded) : null), [encoded]);
}

/* Some renderers want an ArrayBuffer rather than a view of one. */
export function useBuffer(encoded) {
  const bytes = useDecoded(encoded);
  return useMemo(() => (bytes ? bytes.buffer : null), [bytes]);
}

/* A PDF, rendered in the browser from bytes with @embedpdf (pdfium in WASM).
 *
 * Two overrides must stay: the wasm comes from the bundle through Vite's
 * `?url` instead of the default CDN, and the font fallback is off, which the
 * library documents as "no external font requests". The desktop app is
 * offline, so a CDN fetch would break it.
 */

import { useCallback, useMemo } from "react";
import { createPluginRegistration } from "@embedpdf/core";
import { EmbedPDF } from "@embedpdf/core/react";
import { usePdfiumEngine } from "@embedpdf/engines/react";
import pdfiumWasmUrl from "@embedpdf/pdfium/pdfium.wasm?url";
import {
  DocumentContent,
  DocumentManagerPluginPackage,
  useActiveDocument,
  useOpenDocuments,
} from "@embedpdf/plugin-document-manager/react";
import { InteractionManagerPluginPackage } from "@embedpdf/plugin-interaction-manager/react";
import { RenderLayer, RenderPluginPackage } from "@embedpdf/plugin-render/react";
import { RotatePluginPackage, useRotate } from "@embedpdf/plugin-rotate/react";
import { ScrollPluginPackage, Scroller, useScroll } from "@embedpdf/plugin-scroll/react";
import {
  ThumbImg,
  ThumbnailPluginPackage,
  ThumbnailsPane,
} from "@embedpdf/plugin-thumbnail/react";
import { Viewport, ViewportPluginPackage } from "@embedpdf/plugin-viewport/react";
import { ZoomPluginPackage, useZoom } from "@embedpdf/plugin-zoom/react";

import { useBuffer } from "./viewer_bytes.js";
import { ViewerShell, withBoundary } from "./viewer_shell.jsx";

const NOT_OPENED = "Dieses PDF kann nicht geöffnet werden.";

function PdfDocument({ encoded = "", fileName = "" }) {
  const buffer = useBuffer(encoded);
  const { engine, error: engineError } = usePdfiumEngine({
    wasmUrl: pdfiumWasmUrl,
    fontFallback: null,
    /* The worker build resolves its wasm with import.meta.url from the Vite
     * dep cache, where the file is not, and then stays "loading" forever. */
    worker: false,
  });

  /* Memoised on the bytes: a fresh plugin array on every render rebuilds the
   * registry and the document never finishes opening. */
  const plugins = useMemo(
    () =>
      buffer
        ? [
            createPluginRegistration(DocumentManagerPluginPackage, {
              initialDocuments: [
                {
                  buffer,
                  name: fileName || "dokument.pdf",
                  autoActivate: true,
                },
              ],
            }),
            createPluginRegistration(ViewportPluginPackage),
            createPluginRegistration(ScrollPluginPackage),
            createPluginRegistration(RenderPluginPackage),
            createPluginRegistration(InteractionManagerPluginPackage),
            createPluginRegistration(ZoomPluginPackage),
            createPluginRegistration(RotatePluginPackage),
            /* The pane reserves each row from these numbers, so the rail CSS
             * must match them. */
            createPluginRegistration(ThumbnailPluginPackage, {
              width: 116,
              imagePadding: 14,
              labelHeight: 24,
              gap: 10,
              paddingY: 12,
            }),
          ]
        : null,
    [buffer, fileName],
  );

  if (engineError) {
    return <p className="aq-viewer-state">{NOT_OPENED}</p>;
  }
  if (!plugins || !engine) return null;

  return (
    <EmbedPDF engine={engine} plugins={plugins} autoMountDomElements={false}>
      <Opened fileName={fileName} />
    </EmbedPDF>
  );
}

export default withBoundary(PdfDocument);

/* The viewport refuses to register before the document is open;
 * DocumentContent is the library's gate for that. */
function Opened({ fileName }) {
  const { activeDocumentId } = useActiveDocument();
  const open = useOpenDocuments();

  /* autoActivate does not reliably mark the only document active before the
   * first render, so fall back to it. */
  const documentId = activeDocumentId ?? open[0]?.id ?? null;

  if (!documentId) return null;

  return (
    <DocumentContent documentId={documentId}>
      {({ documentState, isLoaded, isError }) => {
        if (isLoaded) return <Pages documentId={documentId} fileName={fileName} />;
        return (
          <p className="aq-viewer-state" data-status={documentState?.status}>
            {isError ? NOT_OPENED : "Wird geöffnet …"}
          </p>
        );
      }}
    </DocumentContent>
  );
}

function Pages({ documentId, fileName }) {
  const { state: scroll, provides: scroller } = useScroll(documentId);
  const { state: zoom, provides: zoomer } = useZoom(documentId);
  const { provides: rotator } = useRotate(documentId);

  const pick = useCallback(
    (index) => scroller?.scrollToPage({ pageNumber: index + 1 }),
    [scroller],
  );
  const onZoom = useCallback(
    (percent) => zoomer?.requestZoom(percent / 100),
    [zoomer],
  );
  const onRotate = useCallback(
    (degrees) => (degrees > 0 ? rotator?.rotateForward() : rotator?.rotateBackward()),
    [rotator],
  );

  const pages = scroll?.totalPages ?? 0;
  const page = (scroll?.currentPage ?? 1) - 1;

  /* The pane is virtualised: each row sits absolutely at the `top` the pane
   * computed. Without it every page lands at zero and only one shows. */
  const rail =
    pages > 1 ? (
      <ThumbnailsPane documentId={documentId} style={{ height: "100%" }}>
        {(meta) => (
          <div
            key={meta.pageIndex}
            style={{
              position: "absolute",
              top: meta.top,
              height: meta.wrapperHeight,
              width: "100%",
            }}
          >
            <button
              type="button"
              className="aq-viewer-thumb"
              aria-current={meta.pageIndex === page ? "true" : undefined}
              aria-label={`Seite ${meta.pageIndex + 1}`}
              onClick={() => pick(meta.pageIndex)}
              style={{ padding: meta.padding ?? 8 }}
            >
              <span
                className="aq-viewer-thumb-page"
                style={{ width: meta.width, height: meta.height }}
              >
                <ThumbImg meta={meta} documentId={documentId} />
              </span>
              <span
                className="aq-viewer-thumb-number"
                style={{
                  height: meta.labelHeight,
                  padding: 0,
                  lineHeight: `${meta.labelHeight}px`,
                }}
              >
                {meta.pageIndex + 1}
              </span>
            </button>
          </div>
        )}
      </ThumbnailsPane>
    ) : null;

  return (
    <ViewerShell
      pageCount={pages}
      active={page}
      onPick={pick}
      rail={rail}
      zoom={Math.round((zoom?.currentZoomLevel ?? 1) * 100)}
      onZoom={onZoom}
      onRotate={onRotate}
    >
      <Viewport documentId={documentId} style={{ height: "100%" }} aria-label={fileName}>
        <Scroller
          documentId={documentId}
          renderPage={({ width, height, pageIndex, scale }) => (
            /* RenderLayer paints only the content; the sheet draws the edge. */
            <div className="aq-viewer-sheet" style={{ width, height }}>
              <RenderLayer
                documentId={documentId}
                pageIndex={pageIndex}
                scale={scale}
                style={{ width: "100%", height: "100%", display: "block" }}
              />
            </div>
          )}
        />
      </Viewport>
    </ViewerShell>
  );
}

/* A Word document, rendered in the browser from bytes.
 *
 * The library's viewer is an editor held read-only: a source is evidence and
 * must not be changed here. The document is imported as a `File`, and the
 * rail previews are painted into canvases by `useDocxPageThumbnails`.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import {
  DocxEditorViewer,
  setWasmSource,
  useDocxEditor,
  useDocxPageThumbnails,
} from "@extend-ai/react-docx";
import docxWasmUrl from "@extend-ai/react-docx/docx_wasm_bg.wasm?url";

import { useDecoded } from "./viewer_bytes.js";
import { ViewerShell, withBoundary } from "./viewer_shell.jsx";

setWasmSource(docxWasmUrl);

const DOCX_TYPE =
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document";

function DocxDocument({ encoded = "", fileName = "" }) {
  const bytes = useDecoded(encoded);
  const editor = useDocxEditor({ initialFileName: fileName });
  const [page, setPage] = useState(0);
  const root = useRef(null);
  const { thumbnails, paintThumbnail } = useDocxPageThumbnails(editor);

  useEffect(() => {
    if (!bytes) return;
    const file = new File([bytes], fileName || "dokument.docx", {
      type: DOCX_TYPE,
    });
    editor.importDocxFile(file);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [bytes, fileName]);

  const renderThumb = useCallback(
    (item) => (
      <canvas
        className="aq-viewer-thumb-canvas"
        ref={(canvas) => paintThumbnail(item.index, canvas)}
      />
    ),
    [paintThumbnail],
  );

  const items = thumbnails.map((one) => ({
    index: one.pageIndex,
    number: one.pageNumber,
    /* Per page: a section break can turn one page landscape. */
    aspect: one.aspectRatio || null,
  }));

  /* The editor has no "go to page", so scroll our own page box by the measured
   * delta to the library's `data-docx-page-index` element. scrollIntoView
   * would also scroll the dialog. */
  const reveal = useCallback((index) => {
    setPage(index);
    const surface = root.current;
    const scroller = surface?.querySelector(".aq-viewer-page");
    const target = surface?.querySelector(`[data-docx-page-index="${index}"]`);
    if (!scroller || !target) return;
    scroller.scrollTop +=
      target.getBoundingClientRect().top - scroller.getBoundingClientRect().top;
  }, []);

  if (!bytes) return null;

  return (
    <ViewerShell
      rootRef={root}
      items={items}
      active={page}
      onPick={reveal}
      renderThumb={renderThumb}
    >
      <DocxEditorViewer
        editor={editor}
        mode="read-only"
        className="aq-viewer-surface"
        onRequestPageReveal={setPage}
        pageBackgroundColor="var(--aq-viewer-sheet)"
        pageGapBackgroundColor="var(--aq-hover)"
      />
    </ViewerShell>
  );
}

export default withBoundary(DocxDocument);

/* A PowerPoint deck, rendered in the browser from bytes.
 *
 * Props arrive camelCased (Python `file_name` is `fileName`). The wasm URL is
 * handed over explicitly because the library resolves it from the Vite dep
 * cache otherwise. The library's own toolbar and rail are off so the deck gets
 * the same header as PDF and Word.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { ReactPptxViewer, setWasmSource } from "@extend-ai/react-pptx";
import "@extend-ai/react-pptx/styles.css";
import pptxWasmUrl from "@extend-ai/react-pptx/pptx_wasm_bg.wasm?url";

import { useDecoded } from "./viewer_bytes.js";
import { ViewerShell, withBoundary } from "./viewer_shell.jsx";

setWasmSource(pptxWasmUrl);

function PptxDeck({ encoded = "", fileName = "" }) {
  const source = useDecoded(encoded);
  const controller = useRef(null);
  const [slides, setSlides] = useState(0);
  const [aspect, setAspect] = useState(null);
  const [slide, setSlide] = useState(0);
  const [zoom, setZoom] = useState(100);

  /* `onLoad` hands over `{kind, document, warnings}`; slide size is in EMU, so
   * only the ratio is useful. */
  const onLoad = useCallback((presentation) => {
    const doc = presentation?.document;
    setSlides(doc?.slides?.length ?? 0);
    const size = doc?.size;
    setAspect(
      size?.widthEmu && size?.heightEmu ? size.widthEmu / size.heightEmu : null,
    );
  }, []);

  const renderThumb = useCallback(
    (item) => <SlideThumb controller={controller} index={item.index} />,
    [],
  );

  const pick = useCallback((index) => {
    setSlide(index);
    controller.current?.goToSlide(index);
  }, []);

  const zoomTo = useCallback((percent) => {
    setZoom(percent);
    controller.current?.setZoom(percent);
  }, []);

  const search = useCallback((query) => {
    if (!query) {
      controller.current?.clearSearchHighlights();
      return;
    }
    const [first] = controller.current?.search(query) ?? [];
    if (first) controller.current.highlightSearchResult(first);
  }, []);

  if (!source) return null;

  const items = Array.from({ length: slides }, (_, index) => ({
    index,
    number: index + 1,
    aspect,
  }));

  return (
    <ViewerShell
      label="Folie"
      railLabel="Folien"
      items={items}
      active={slide}
      onPick={pick}
      renderThumb={renderThumb}
      zoom={zoom}
      onZoom={zoomTo}
      onSearch={search}
    >
      <ReactPptxViewer
        ref={controller}
        source={source}
        aria-label={fileName}
        showToolbar={false}
        showThumbnails={false}
        slideIndex={slide}
        zoom={zoom}
        fitMode="width"
        onLoad={onLoad}
        onSlideChange={setSlide}
        height="100%"
        style={{ height: "100%" }}
      />
    </ViewerShell>
  );
}

/* The controller paints into a node we own and returns its own teardown. */
function SlideThumb({ controller, index }) {
  const host = useRef(null);

  useEffect(() => {
    let release;
    let live = true;
    const node = host.current;
    if (!node || !controller.current) return undefined;
    controller.current
      .renderThumbnail(index, node)
      .then((teardown) => {
        if (live) release = teardown;
        else teardown?.();
      })
      .catch(() => {});
    return () => {
      live = false;
      release?.();
    };
  }, [controller, index]);

  return <span ref={host} className="aq-viewer-thumb-canvas" />;
}

export default withBoundary(PptxDeck);

/* Document viewers of the offer workshop (alloq_offer/workshop/viewer).
   `.aq-viewer` is the sized box around each viewer; `.aq-viewer-shell` and
   below are the header and page rail from viewer_shell.jsx. The rail
   breakpoint is measured in the JSX and set as `data-rail-mode`. */
:root {
  --aq-viewer-height: 72vh;
  --aq-viewer-rail-width: 188px;
  --aq-viewer-sheet: #ffffff; /* paper stays white in dark mode */
}

.aq-viewer {
  display: flex;
  flex-direction: column;
  height: var(--aq-viewer-height);
  min-height: 0;
  overflow: hidden;
  border: 1px solid var(--aq-border);
  border-radius: 12px;
  background: var(--aq-surface);
}

.aq-viewer-surface {
  flex: 1 1 0%;
  min-height: 0;
}

.aq-viewer-shell {
  display: flex;
  flex-direction: column;
  min-height: 0;
  height: 100%;
}

.aq-viewer-broken {
  display: flex;
  flex: 1 1 0%;
  flex-direction: column;
  gap: 6px;
  align-items: center;
  justify-content: center;
  min-height: 0;
  padding: 24px;
  color: var(--aq-text);
  font-size: 13px;
  text-align: center;
}

.aq-viewer-broken p {
  margin: 0;
}

.aq-viewer-broken-detail {
  max-width: 46ch;
  color: var(--aq-text-muted);
}

/* Header */

.aq-viewer-header {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 4px;
  height: 48px;
  padding: 0 10px;
  border-bottom: 1px solid var(--aq-separator);
  background: var(--aq-surface);
}

.aq-viewer-spacer {
  flex: 1 1 auto;
}

.aq-viewer-count {
  margin: 0 0 0 6px;
  color: var(--aq-text-muted);
  font-size: 13px;
  white-space: nowrap;
}

.aq-viewer-count b {
  color: var(--aq-text);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.aq-viewer-icon {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 7px;
  background: none;
  color: var(--aq-text-muted);
  cursor: pointer;
  transition: background 120ms ease, color 120ms ease, border-color 120ms ease;
}

.aq-viewer-icon:hover {
  background: var(--aq-hover);
  color: var(--aq-text);
}

.aq-viewer-icon[aria-pressed="true"] {
  border-color: var(--aq-border);
  background: var(--aq-hover);
  color: var(--aq-text);
}

.aq-viewer-divider {
  flex-shrink: 0;
  width: 1px;
  height: 20px;
  margin: 0 6px;
  background: var(--aq-separator);
}

.aq-viewer-zoom {
  position: relative;
  display: inline-flex;
  align-items: center;
}

.aq-viewer-zoom select {
  height: 30px;
  padding: 0 26px 0 10px;
  border: 1px solid var(--aq-border);
  border-radius: 7px;
  background: var(--aq-surface);
  color: var(--aq-text);
  font: inherit;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
  appearance: none;
}

.aq-viewer-zoom svg {
  position: absolute;
  right: 8px;
  color: var(--aq-text-muted);
  pointer-events: none;
}

.aq-viewer-find {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 30px;
  padding: 0 6px 0 10px;
  border: 1px solid var(--aq-border);
  border-radius: 7px;
  color: var(--aq-text-muted);
}

.aq-viewer-find input {
  width: 130px;
  border: none;
  background: none;
  color: var(--aq-text);
  font: inherit;
  font-size: 13px;
  outline: none;
}

.aq-viewer-find button {
  display: inline-flex;
  align-items: center;
  padding: 2px;
  border: none;
  border-radius: 5px;
  background: none;
  color: inherit;
  cursor: pointer;
}

.aq-viewer-find button:hover {
  background: var(--aq-hover);
}

/* Rail and page */

.aq-viewer-body {
  position: relative;
  display: flex;
  flex: 1 1 0%;
  min-height: 0;
}

.aq-viewer-rail {
  position: relative;
  flex: 0 0 var(--aq-viewer-rail-width);
  width: var(--aq-viewer-rail-width);
  overflow-y: auto;
  padding: 16px 14px;
  border-right: 1px solid var(--aq-separator);
  background: var(--aq-surface);
}

/* A self-virtualising rail (PDF) owns its scrolling and its vertical padding;
   extra padding here would be counted twice. */
.aq-viewer-rail[data-rail-kind="pane"] {
  overflow: hidden;
  padding: 0 14px;
}

.aq-viewer-rail[data-rail-kind="pane"] .aq-viewer-thumb {
  height: 100%;
  margin: 0;
}

.aq-viewer-rail[data-rail-kind="pane"] .aq-viewer-thumb-page {
  margin: 0 auto;
}

.aq-viewer-shell[data-rail-mode="overlay"] .aq-viewer-rail {
  position: absolute;
  inset-block: 0;
  inset-inline-start: 0;
  z-index: 2;
  box-shadow: var(--aq-card-shadow);
}

.aq-viewer-scrim {
  position: absolute;
  inset: 0;
  z-index: 1;
  background: rgb(0 0 0 / 28%);
}

.aq-viewer-page {
  flex: 1 1 0%;
  min-width: 0;
  min-height: 0;
  overflow: auto;
  background: var(--aq-hover);
}

/* Renderers paint page content only; the sheet draws the paper edge. */
.aq-viewer-sheet {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--aq-border);
  border-radius: 2px;
  background: var(--aq-viewer-sheet);
  box-shadow: var(--aq-card-shadow);
}

.aq-viewer-thumb {
  display: block;
  width: 100%;
  margin-bottom: 6px;
  padding: 14px; /* matches the PDF pane's imagePadding */
  border: none;
  border-radius: 10px;
  background: none;
  cursor: pointer;
  transition: background 120ms ease;
}

.aq-viewer-thumb:hover,
.aq-viewer-thumb[aria-current="true"] {
  background: var(--aq-hover);
}

.aq-viewer-thumb[aria-current="true"] {
  background: var(--aq-accent-soft);
}

/* A4 is the fallback; viewers that know the page shape set aspect-ratio. */
.aq-viewer-thumb-page {
  display: block;
  overflow: hidden;
  border: 1px solid var(--aq-border);
  border-radius: 3px;
  background: var(--aq-viewer-sheet);
  box-shadow: 0 1px 2px rgb(0 0 0 / 6%);
  aspect-ratio: 1 / 1.414;
}

.aq-viewer-thumb-canvas,
.aq-viewer-thumb-page > * {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.aq-viewer-thumb-number {
  display: block;
  padding: 10px 0 0;
  color: var(--aq-text-muted);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  text-align: center;
}

.aq-viewer-thumb[aria-current="true"] .aq-viewer-thumb-number {
  color: var(--aq-text);
  font-weight: 600;
}

.aq-viewer-state {
  margin: 0;
  padding: 24px;
  color: var(--aq-text-muted);
  font-size: 13px;
  text-align: center;
}

